const post = (type, text) => self.postMessage({ kind: 'log', type, text });
const origConsole = self.console;
self.console = {
  ...origConsole,
  log:   (...a) => post('log',   a.map(formatVal).join(' ')),
  warn:  (...a) => post('warn',  a.map(formatVal).join(' ')),
  error: (...a) => post('error', a.map(formatVal).join(' ')),
};
